class Cat {
    private String name;
    private int fish;

    Cat(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public int getFish() {
        return fish;
    }

    public void setFish(int fish) {
        if (fish < 0) {
            System.out.println("鱼干数不能是负的喵");
            return;
        }
        this.fish = fish;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat("{name}");
